"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View0 from "./components/feature-sections/variants/01-visual-benefits";
const variants = {"visual-benefits":View0};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "visual-benefits"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "visual-benefits", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { MotionConfig, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisFeatureContent, ArtemisFeatureItem } from "../content";
const DEFAULT = {
    headline: "A clearer way to move forward.",
    items: [
        { title: "Your work, on your terms", description: "Keep ownership of your data and decisions. Build a workspace that fits the way your team thinks." },
        { title: "Everything in the right place", description: "Bring your notes, tools, and projects together, so a good idea never gets lost between tabs." },
        { title: "Less setup. More progress.", description: "Turn everyday routines into repeatable workflows and give your team time for the work that matters." },
    ],
    cta: { label: "Find your flow", href: "/signup" },
} satisfies ArtemisFeatureContent;
const ROW_HIDDEN = { opacity: 0, y: 12 };
const ROW_SHOWN = { opacity: 1, y: 0 };
const ROW_VIEWPORT = { once: true, amount: 0.3 };
const rowTransition = (i: number) => ({ duration: 0.45, ease: ARTEMIS_EASE_OUT, delay: i * 0.08 });
function FingerprintIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-fingerprint-pattern ${className}`} aria-hidden="true">
      <path d="M12 10a2 2 0 0 0-2 2c0 1.02-.1 2.51-.26 4"/>
      <path d="M14 13.12c0 2.38 0 6.38-1 8.88"/>
      <path d="M17.29 21.02c.12-.6.43-2.3.5-3.02"/>
      <path d="M2 12a10 10 0 0 1 18-6"/>
      <path d="M2 16h.01"/>
      <path d="M21.8 16c.2-2 .131-5.354 0-6"/>
      <path d="M5 19.5C5.5 18 6 15 6 12a6 6 0 0 1 .34-2"/>
      <path d="M8.65 22c.21-.66.45-1.32.57-2"/>
      <path d="M9 6.8a6 6 0 0 1 9 5.2v2"/>
    </svg>);
}
function LayersIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-layers ${className}`} aria-hidden="true">
      <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
      <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
      <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
    </svg>);
}
function WorkflowIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-workflow ${className}`} aria-hidden="true">
      <rect width="8" height="8" x="3" y="3" rx="2"/>
      <path d="M7 11v4a2 2 0 0 0 2 2h4"/>
      <rect width="8" height="8" x="13" y="13" rx="2"/>
    </svg>);
}
const ICONS = [FingerprintIcon, LayersIcon, WorkflowIcon];
export default function FeatureSectionsVisualBenefits({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const items: ArtemisFeatureItem[] = copy.items;
    const reduced = useReducedMotion() ?? false;
    return (<MotionConfig reducedMotion="user">
      <section className="art:w-full art:bg-background art:px-6 art:py-12 art:text-foreground art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-16">
        <div className="art:mx-auto art:max-w-6xl">
          <h2 className="art:mx-auto art:mb-10 art:max-w-2xl art:text-balance art:text-center art:text-4xl art:font-medium art:tracking-tight art:@min-[640px]/artemis:mb-14">
            {copy.headline}
            {copy.headlineAccent ? ` ${copy.headlineAccent}` : null}
          </h2>
          <div className="art:grid art:gap-8 art:@min-[768px]/artemis:grid-cols-2 art:@min-[768px]/artemis:gap-12 art:@min-[1024px]/artemis:gap-16">
            <div className="art:relative art:min-h-80 art:overflow-hidden art:rounded-3xl art:@min-[768px]/artemis:min-h-96">
              <div aria-hidden="true" className="art:absolute art:inset-0 art:overflow-hidden" style={{ background: "radial-gradient(ellipse at 75% 15%, #fff4da, transparent 60%), linear-gradient(140deg, #e2eef1, #f2e9dd 60%, #eacfbf)" }}>
                <div className="art:absolute art:inset-0 art:opacity-30" style={{ backgroundImage: "radial-gradient(#fff 0.75px, transparent 0.75px)", backgroundSize: "12px 12px" }}/>
                <div className="art:absolute art:-left-1/4 art:top-1/2 art:h-1/2 art:w-full art:-rotate-45 art:rounded-full" style={{ background: "linear-gradient(180deg, transparent, rgba(255,255,255,.65), transparent)", filter: "blur(22px)" }}/>
                <div className="art:absolute art:inset-0 art:flex art:items-center art:justify-center" style={{ perspective: "1000px" }}>
                  <div className="art:relative art:h-64 art:w-64 art:@min-[640px]/artemis:h-72 art:@min-[640px]/artemis:w-72" style={{ transform: "rotateX(48deg) rotateZ(-32deg)", transformStyle: "preserve-3d" }}>
                    <div className="art:absolute art:inset-0 art:overflow-hidden art:rounded-3xl" style={{ background: "linear-gradient(135deg, rgba(255,255,255,0.6), rgba(155,199,204,.38), rgba(247,203,163,.5))", border: "1px solid rgba(255,255,255,.85)", transformStyle: "preserve-3d", transform: "translateZ(-65px)" }}>
                      <div className="art:absolute art:inset-5 art:rounded-2xl" style={{ border: "1px solid rgba(255,255,255,.55)" }}/>
                    </div>
                    <div className="art:absolute art:inset-0 art:overflow-hidden art:rounded-3xl" style={{ background: "linear-gradient(135deg, rgba(255,255,255,0.52), rgba(155,199,204,.38), rgba(247,203,163,.5))", border: "1px solid rgba(255,255,255,.85)", transformStyle: "preserve-3d", transform: "translateY(-8px) translateZ(-27px)" }}>
                      <div className="art:absolute art:inset-5 art:rounded-2xl" style={{ border: "1px solid rgba(255,255,255,.55)" }}/>
                    </div>
                    <div className="art:absolute art:inset-0 art:overflow-hidden art:rounded-3xl" style={{ background: "linear-gradient(135deg, rgba(255,255,255,0.43999999999999995), rgba(155,199,204,.38), rgba(247,203,163,.5))", border: "1px solid rgba(255,255,255,.85)", transformStyle: "preserve-3d", transform: "translateY(-16px) translateZ(11px)" }}>
                      <div className="art:absolute art:inset-5 art:rounded-2xl" style={{ border: "1px solid rgba(255,255,255,.55)" }}/>
                    </div>
                    <div className="art:absolute art:inset-0 art:overflow-hidden art:rounded-3xl" style={{ background: "linear-gradient(135deg, rgba(255,255,255,.86), rgba(255,244,225,.48) 45%, rgba(180,220,224,.62))", border: "1px solid rgba(255,255,255,.85)", transformStyle: "preserve-3d", transform: "translateY(-24px) translateZ(49px)" }}>
                      <div className="art:absolute art:inset-5 art:rounded-2xl" style={{ border: "1px solid rgba(255,255,255,.55)" }}/>
                      <div className="art:absolute art:inset-12 art:rounded-full" style={{ background: "conic-gradient(from 45deg, rgba(150,191,199,.1), rgba(255,255,255,.95), rgba(224,180,147,.45), rgba(162,208,211,.45), rgba(150,191,199,.1))", padding: "18px" }}>
                        <div className="art:size-full art:rounded-full" style={{ background: "linear-gradient(135deg, #e5eff0, #f5e9d9)" }}/>
                      </div>
                      <div className="art:absolute art:left-1/2 art:top-1/2 art:size-10 art:-translate-x-1/2 art:-translate-y-1/2 art:rounded-full" style={{ background: "radial-gradient(circle at 30% 25%, #ffffff, #d1e5e4 60%, #aecbc9)" }}/>
                    </div>
                  </div>
                </div>
                <div className="art:absolute art:bottom-8 art:left-8 art:flex art:gap-1.5">
                  <span className="art:size-1 art:rounded-full art:bg-foreground/20"/>
                  <span className="art:size-1 art:rounded-full art:bg-foreground/20"/>
                  <span className="art:size-1 art:rounded-full art:bg-foreground/20"/>
                </div>
                <div className="art:absolute art:inset-0 art:dark:bg-background/20"/>
              </div>
            </div>
            <div className="art:flex art:flex-col art:py-1">
              <div className="art:space-y-7 art:@min-[640px]/artemis:space-y-9">
                {items.map((item, i) => {
            const Icon = item.icon ?? ICONS[i % ICONS.length];
            return (<motion.div key={i} className="art:flex art:gap-4" initial={ROW_HIDDEN} whileInView={ROW_SHOWN} viewport={ROW_VIEWPORT} transition={rowTransition(i)}>
                  <span aria-hidden="true" className="art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                    <Icon className="art:size-5"/>
                  </span>
                  <div className="art:pt-1">
                    <h3 className="art:text-xl art:font-medium art:tracking-tight">
                      {item.title}
                    </h3>
                    <p className="art:mt-2 art:text-sm art:leading-6 art:text-muted-foreground">
                      {item.description}
                    </p>
                  </div>
                </motion.div>);
        })}
              </div>
              {copy.cta ? (<motion.a whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-8 art:h-9 art:w-full art:rounded-full" href={copy.cta.href} tabIndex={0}>
                <span>
                  {copy.cta.label}
                </span>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                  <path d="M5 12h14"/>
                  <path d="m12 5 7 7-7 7"/>
                </svg>
              </motion.a>) : null}
            </div>
          </div>
        </div>
      </section>
    </MotionConfig>);
}
